import os
import ast

keywords_write = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]

def analyze_file(filepath):
    with open(filepath, "r", encoding="utf-8") as f:
        source = f.read()

    try:
        tree = ast.parse(source, filename=filepath)
    except Exception as e:
        print(f"Error parsing {filepath}: {e}")
        return

    # Let's find if legacy_auth is imported
    has_legacy_auth_import = False
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            if node.module == "app.auth":
                for alias in node.names:
                    if alias.name == "legacy_auth":
                        has_legacy_auth_import = True

    if not has_legacy_auth_import:
        return

    print(f"\n--- File: {filepath} ---")

    # Let's get the lines of the file to extract function source with comments
    lines = source.splitlines()

    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            # Check if legacy_auth is called in this function
            calls_legacy_auth = False
            for subnode in ast.walk(node):
                if isinstance(subnode, ast.Call) and isinstance(subnode.func, ast.Name) and subnode.func.id == "legacy_auth":
                    calls_legacy_auth = True
                    break

            if calls_legacy_auth:
                # Extract the source lines of this function (including decorators if any, but let's just use lines)
                start_line = node.lineno - 1
                # Find the end of the function (by looking at the next function or end of file, or ast node end_lineno)
                end_line = getattr(node, "end_lineno", len(lines))
                func_lines = lines[start_line:end_line]
                func_source = "\n".join(func_lines)

                # Check for keywords
                found_keywords = [kw for kw in keywords_write if kw in func_source]

                # Also do a case-insensitive check just in case
                found_keywords_lower = [kw for kw in keywords_write if kw.lower() in func_source.lower()]

                print(f"  Function: {node.name}")
                print(f"    Calls legacy_auth: Yes")
                print(f"    Found keywords (case-sensitive): {found_keywords}")
                print(f"    Found keywords (case-insensitive): {found_keywords_lower}")
                # Print function lines for verification
                print("    Source:")
                for l in func_lines:
                    print(f"      {l}")

if __name__ == "__main__":
    for root, dirs, files in os.walk("app"):
        for file in files:
            if file.endswith(".py") and file != "auth.py":
                analyze_file(os.path.join(root, file))

